  intros w a Hw Hin; unfold PML.ll_foot_xsrc in Hw; cbn [In map fst snd] in Hw;
  repeat (destruct Hw as [<-|Hw]; [unfold L5.in_rng in Hin; cbn [fst snd] in Hin; first [left; lia | right; foot_in]|]); destruct Hw.
