  assert (a < 0xfb000) by (destruct Ha as [(iv & Hiv & Hr)|Hr]; [unfold PML.ll_foot_xsrc in Hiv; repeat (destruct Hiv as [<-|Hiv]; [cbn [fst snd] in Hr; lia|]); destruct Hiv | unfold PML.IMG_RO_HI in Hr; lia]); ow.
