  repeat (destruct Hw as [<-|Hw]; [cbn [fst snd]; first [left; lia | right; split; [lia|]; split; [lia|]; let a := fresh "a" in let Hi := fresh "Hi" in intros a Hi; unfold L5.in_rng in Hi; cbn [fst snd] in Hi; foot_in]|]); destruct Hw.
